<script setup lang="ts">
import { computed, nextTick, watch } from 'vue'
import type { BotWorkspaceBot, JobProjection } from '#shared/botWorkspace'
import { useBotWorkspace } from '~/composables/useBotWorkspace'
import { botKey, hasAttention } from '~/utils/bots/workspace'
import type { BotView } from '~/utils/bots/workspace'
import { t, tl } from '~/utils/i18n'
import BotGraph from './BotGraph.vue'
import BotGraphObservation from './BotGraphObservation.vue'
import BotInspector from './BotInspector.vue'
const props = defineProps<{ sampleMode: boolean }>()
const workspace = useBotWorkspace(props.sampleMode)
const { snapshot, bots, loading, error, authRequired, online, stale, ready, selectedBot, selectedJob, selectedBotKey, selectionKey, inspectorOpen, view, tab, draft, answers, selectedOperations, details, detailErrors, detailLoading, sending } = workspace
const groups = computed(() => selectedBot.value ? [selectedBot.value] : bots.value)
const allJobs = computed(() => bots.value.flatMap(entry => entry.jobs.map(job => ({ entry, job }))))
const attention = computed(() => allJobs.value.filter(item => hasAttention(item.job)))
const running = computed(() => allJobs.value.filter(item => item.job.state === 'running').length)
const views: BotView[] = ['list', 'graph', 'timeline']
const timeline = computed(() => details[workspace.detailKey('events')])
const timelineError = computed(() => detailErrors[workspace.detailKey('events')])
let selectionOrigin: HTMLElement | null = null
function selectJob(entry: BotWorkspaceBot, job: JobProjection) {
  selectionOrigin = document.activeElement instanceof HTMLElement ? document.activeElement : null
  workspace.selectJob(entry, job)
}
function backToJobs() {
  inspectorOpen.value = false
  nextTick(() => { if (selectionOrigin?.isConnected) selectionOrigin.focus({ preventScroll: true }) })
}
function allBots() { selectedBotKey.value = ''; inspectorOpen.value = false }
function inspectAttention(entry: BotWorkspaceBot, job: JobProjection) { tab.value = 'attention'; selectJob(entry, job) }
watch([view, selectionKey], () => { if (view.value === 'timeline' && selectionKey.value) workspace.loadDetail('events') })
</script>

<template>
  <main class="bot-workspace" :class="{ 'inspector-open': inspectorOpen && selectedJob }">
    <header class="workspace-head">
      <NuxtLink to="/" class="workspace-back icon-btn" :aria-label="t('Back to agents')"><UIcon name="i-lucide-chevron-left" /></NuxtLink>
      <h1>{{ t('Bots') }}</h1><span class="workspace-kind">{{ t(sampleMode ? 'Sample' : 'Workspace') }}</span>
      <NuxtLink v-if="!sampleMode" to="/graphs" class="sample-link">{{ t('Graph definitions') }}</NuxtLink>
      <NuxtLink v-if="!sampleMode" to="/bots?sample=1" class="sample-link">{{ t('Explore sample') }}</NuxtLink>
      <button v-if="!sampleMode" type="button" class="icon-btn refresh" :disabled="loading || !online" :aria-label="t('Refresh Bots')" @click="workspace.reload"><UIcon name="i-lucide-refresh-cw" /></button>
      <NuxtLink v-else to="/bots" class="sample-link">{{ t('Exit sample') }}</NuxtLink>
    </header>
    <div v-if="sampleMode" class="sample-banner" role="note"><strong>{{ t('Sample workspace') }}</strong><span>{{ t('Fictional data · no production Bot requests. Actions change this sample only; reload resets it.') }}</span></div>
    <div v-else-if="!online || (snapshot && stale && selectedJob)" class="freshness-banner" role="status">{{ t(!online ? 'Offline · read only. Nothing will be sent when the connection returns.' : 'Stale observation · controls are disabled until a fresh snapshot arrives.') }}</div>
    <div class="workspace-layout">
      <aside class="bot-roster" :aria-label="t('Named Bot roster')">
        <div class="roster-heading"><h2>{{ t('Roster') }}</h2><span>{{ bots.length }}</span></div>
        <button type="button" class="roster-all" :class="{ selected: !selectedBotKey }" :aria-pressed="!selectedBotKey" @click="allBots"><UIcon name="i-lucide-layout-list" />{{ t('All Bots') }}</button>
        <button v-for="entry in bots" :key="botKey(entry)" type="button" class="roster-bot" :class="{ selected: selectedBotKey === botKey(entry) }" :aria-pressed="selectedBotKey === botKey(entry)" @click="workspace.selectBot(entry)">
          <span class="roster-identity"><i :class="entry.bot.worker.state" aria-hidden="true" /><strong>{{ entry.bot.bot_name }}</strong><b v-if="entry.jobs.some(hasAttention)" class="attention-square" :aria-label="t('Needs attention')">!</b></span>
          <span class="roster-meta">{{ tl(`${entry.bot.jobs_total} Jobs`) }} · {{ t(entry.bot.worker.state) }}</span>
          <small>{{ snapshot?.sources.find(source => source.id === entry.source_id)?.label || entry.source_id }}</small>
        </button>
        <p class="roster-note">{{ t('Bot names are fixed. Select a Job to inspect or control its work.') }}</p>
        <div v-if="!sampleMode" class="source-list">
          <h3>{{ t('Sources') }}</h3><article v-for="source in snapshot?.sources || []" :key="source.id"><strong>{{ source.label }}</strong><span>{{ t(source.state) }}</span><p v-if="source.message">{{ t(source.message) }}</p></article>
          <p v-if="snapshot?.observed_at" class="observed-at">{{ t('Observed') }}<time :datetime="snapshot.observed_at">{{ snapshot.observed_at }}</time></p>
        </div>
      </aside>
      <section class="workspace-main" :aria-label="t('Bot Jobs')">
        <div class="main-scroll">
          <div class="workspace-intro"><p class="section-label">{{ t('Observation / attention / control') }}</p><h2>{{ t('The work, by Job.') }}</h2><p>{{ t('Inspect a named Bot, answer what needs you, and keep requests separate from actual outcomes.') }}</p></div>
          <div v-if="error" class="workspace-error" role="alert"><h3>{{ t(authRequired ? 'Passkey required' : 'Source unavailable') }}</h3><p>{{ t(error) }}</p><NuxtLink v-if="authRequired" to="/settings?section=security" class="mono-btn">{{ t('Open Security settings') }}</NuxtLink><button v-else type="button" class="mono-btn" :disabled="loading || !online" @click="workspace.reload">{{ t('Try refresh') }}</button></div>
          <section v-if="!snapshot && loading" class="empty-state" role="status"><p>{{ t('Reading configured Bot sources…') }}</p></section>
          <section v-else-if="snapshot && !snapshot.configured" class="empty-state"><UIcon name="i-lucide-bot" /><h3>{{ t('No Bot sources configured') }}</h3><p>{{ t('Add a trusted local OMP source to bot-sources.json in the server data directory. This workspace cannot create executable paths or profiles from the browser.') }}</p><p>{{ t('A valid passkey session is required even when the ordinary app lock is off.') }}</p><NuxtLink to="/bots?sample=1" class="mono-btn">{{ t('Inspect the sample workspace') }}</NuxtLink></section>
          <template v-if="snapshot?.configured">
            <div class="attention-summary"><div><strong>{{ attention.length }}</strong><span>{{ t('Need attention') }}</span></div><div><strong>{{ running }}</strong><span>{{ t('Running') }}</span></div><div><strong>{{ allJobs.length }}</strong><span>{{ t('Observed Jobs') }}</span></div></div>
            <p v-if="!snapshot.complete || bots.some(entry => !entry.complete)" class="completeness-note" role="status">{{ t('Partial observation: a source reached the bounded listing limit. Counts and Jobs shown here are not a complete inventory.') }}</p>
            <section v-if="attention.length" class="attention-list"><h3>{{ t('Needs you first') }}</h3><button v-for="item in attention" :key="`${botKey(item.entry)}:${item.job.job_id}`" type="button" @click="inspectAttention(item.entry, item.job)"><span class="attention-mark" aria-hidden="true">!</span><span><strong>{{ item.entry.bot.bot_name }}</strong><small>{{ item.job.wait?.message || item.job.error?.message || t('Inspect this Job') }}</small></span><UIcon name="i-lucide-chevron-right" /></button></section>
            <div class="view-bar"><h3>{{ selectedBot?.bot.bot_name || t('All Bots') }}</h3><nav :aria-label="t('Workspace view')"><button v-for="value in views" :key="value" type="button" :aria-pressed="view === value" @click="view = value">{{ t(value === 'list' ? 'List' : value === 'graph' ? 'Graph' : 'Timeline') }}</button></nav></div>
            <div v-if="view === 'list'" class="job-groups"><section v-for="entry in groups" :key="botKey(entry)" class="job-group"><header><h3>{{ entry.bot.bot_name }}</h3><span>{{ tl(`${entry.jobs.length} observed Jobs`) }}</span></header><button v-for="job in entry.jobs" :key="job.job_id" type="button" class="job-row" :class="{ selected: selectionKey === `${botKey(entry)}:${job.job_id}` }" :aria-pressed="selectionKey === `${botKey(entry)}:${job.job_id}`" @click="selectJob(entry, job)"><span class="job-row-state" :class="job.state"><i aria-hidden="true" />{{ t(job.state.replaceAll('_', ' ')) }}</span><strong>{{ job.goal_preview }}</strong><span class="job-row-bottom"><code>{{ job.job_id }}</code><span v-if="job.progress">{{ tl(`${job.progress.completed}/${job.progress.total} ${job.progress.unit}`) }}</span><UIcon name="i-lucide-chevron-right" /></span></button><p v-if="!entry.jobs.length" class="no-jobs">{{ t('No Jobs reported for this Bot.') }}</p></section></div>
            <BotGraph v-else-if="view === 'graph' && sampleMode" :bots="bots" :selected-job-id="selectedJob?.job_id || ''" @select="selectJob" />
            <BotGraphObservation v-else-if="view === 'graph'" :bots="bots" @select="selectJob" />
            <section v-else-if="view === 'timeline'" class="timeline"><template v-if="selectedJob"><h3>{{ tl(`Events · ${selectedBot?.bot.bot_name} / ${selectedJob.job_id}`) }}</h3><p>{{ t('Actual Job events, fetched on demand. A request event is not a completion event.') }}</p><article v-for="item in timeline?.items || []" :key="item.id"><span class="timeline-square" aria-hidden="true" /><div><time v-if="item.at" :datetime="item.at">{{ item.at }}</time><h4>{{ item.label }}</h4><p v-if="item.text">{{ item.text }}</p></div></article><p v-if="timeline && !timeline.items.length">{{ t('No events in this page.') }}</p><p v-if="timelineError" class="workspace-error">{{ t(timelineError) }}</p><button type="button" class="mono-btn" :disabled="detailLoading" @click="workspace.loadDetail('events')">{{ t('Refresh events') }}</button><button v-if="timeline?.next" type="button" class="mono-btn" :disabled="detailLoading" @click="workspace.loadDetail('events', '', timeline.next)">{{ t('Load next page') }}</button></template><template v-else><h3>{{ t('Select a Job first') }}</h3><p>{{ t('Events are scoped to an explicitly selected Job, never merged into an invented execution graph.') }}</p><button type="button" class="mono-btn" @click="view = 'list'">{{ t('Choose from the list') }}</button></template></section>
            <p v-if="!bots.length" class="empty-state">{{ t('No Bots were returned by the configured sources. Check source readiness in the roster.') }}</p>
          </template>
        </div>
      </section>
      <div class="inspector-slot" :class="{ open: inspectorOpen && selectedJob }">
        <BotInspector v-if="selectedBot && selectedJob" :entry="selectedBot" :job="selectedJob" :visible="inspectorOpen" :selection-key="selectionKey" :tab="tab" :ready="ready" :sample-mode="sampleMode" :draft="draft" :answers="answers" :details="details" :detail-errors="detailErrors" :detail-loading="detailLoading" :operations="selectedOperations" :sending="sending" @back="backToJobs" @update:tab="tab = $event" @update:draft="draft = $event" @answer="(key, value) => answers[key] = value" @command="workspace.command" @detail="workspace.loadDetail" @reconcile="workspace.reconcile" @retry="workspace.retry" />
        <div v-else class="inspector-placeholder"><UIcon name="i-lucide-panel-right" /><p>{{ t('Select a Job') }}</p><span>{{ t('Questions, messages, artifacts and scoped controls appear here.') }}</span></div>
      </div>
    </div>
  </main>
</template>

<style scoped>
