.sample-banner { display: flex; align-items: center; gap: 16px; padding: 12px 20px; border-bottom: 1px solid var(--line); background: var(--surface); font-size: 11px; line-height: 1.6; }.sample-banner strong { font: 10px var(--mono); text-transform: uppercase; color: var(--accent); white-space: nowrap; }.sample-banner span { color: var(--text-2); }.freshness-banner { font-size: 11px; color: var(--blocked); padding: 12px 20px; border-bottom: 1px solid var(--line); }
