.roster-all, .roster-bot { border: 1px solid transparent; background: none; color: var(--text); width: 100%; text-align: left; cursor: pointer; }.roster-all { display: flex; gap: 10px; align-items: center; min-height: 44px; padding: 10px; font: 11px var(--mono); margin-bottom: 8px; }.roster-bot { padding: 14px 10px; border-top-color: var(--line-soft); }.roster-bot.selected, .roster-all.selected { background: var(--surface); border-color: var(--line); }.roster-identity { display: flex; gap: 8px; align-items: center; }.roster-identity > i { width: 7px; height: 7px; border: 1px solid var(--muted); flex-shrink: 0; }.roster-identity > i.online { border-color: var(--idle); }.roster-identity > i.offline { background: var(--muted); }.roster-identity strong { font: 16px var(--display); overflow-wrap: anywhere; }.attention-square { font: 10px var(--mono); color: var(--blocked); margin-left: auto; }.roster-meta { display: block; font: 10px var(--mono); color: var(--text-2); margin: 10px 0 6px 15px; }.roster-bot > small { display: block; font-size: 10px; color: var(--muted); margin-left: 15px; overflow-wrap: anywhere; }.roster-note { padding: 12px 10px; font-size: 11px; color: var(--muted); line-height: 1.7; }
